-- 730 — Identité : plus de logo de repli emprunté (audit de cohérence des profils, lot L1).
--
-- Sans logo enregistré, factures, devis, BL, relances, bons de commande et tickets imprimaient le
-- logo d'Ofauria (« Boulangerie · Pâtisserie ») fourni avec le code : tout autre client sortait
-- ses documents avec la marque d'un autre. Le repli est retiré du code ; sans logo, l'en-tête
-- porte le nom de la société.
--
-- Pour qu'Ofauria garde son logo sur ses documents, il est enregistré dans ses paramètres
-- (data URI, comme un logo téléversé), seulement là où la société s'appelle OFAURIA et n'a pas
-- encore de logo. Une installation neuve passe par scripts/client-install.sh, qui remet
-- l'identité à blanc (nom, sous-titre, logo).
--
-- Rollback : UPDATE company_settings SET logo_url = NULL WHERE id = 1 AND logo_url LIKE 'data:image/png;base64,iVBOR%' (logo d'Ofauria).

UPDATE company_settings
   SET logo_url = 'data:image/png;base64,'
 WHERE id = 1 AND COALESCE(logo_url, '') = '' AND upper(btrim(company_name)) = 'OFAURIA';
